-- ======================================================================
-- 20260712130000_case_insensitive_usernames.sql
-- ======================================================================

-- Usernames are case-insensitive: "Max" and "max" must be the same account.
-- Normalize everything that already exists to lowercase.
--
-- NOTE: this fails if two profiles already differ only by case. Check first:
--   SELECT lower(username), count(*) FROM profiles
--   GROUP BY lower(username) HAVING count(*) > 1;
UPDATE profiles SET username = lower(username) WHERE username <> lower(username);

-- Belt-and-braces: even if some code path forgets to normalize, the database
-- refuses two usernames differing only by case.
CREATE UNIQUE INDEX IF NOT EXISTS idx_profiles_username_lower
ON profiles (lower(username));

-- ======================================================================
-- 20260723120000_tool_approved_notification.sql
-- ======================================================================

-- Allow the new "tool_approved" notification type (sent when an admin resolves
-- a user's tool ticket).
ALTER TABLE notifications DROP CONSTRAINT IF EXISTS notifications_type_check;
ALTER TABLE notifications ADD CONSTRAINT notifications_type_check
  CHECK (type IN ('follow', 'post_star', 'post_comment', 'tool_approved'));

-- ======================================================================
-- 20260730120000_enable_rls_all_public_tables.sql
-- ======================================================================

-- Enable Row Level Security on every table in the public schema.
--
-- Supabase auto-exposes a REST API for public tables using the public `anon`
-- key (shipped in the browser bundle). Without RLS, anyone with that key can
-- read/write these tables directly, bypassing the Go backend entirely — most
-- critically account_claims, which holds single-use claim tokens (credentials).
--
-- We enable RLS with NO policies: the anon/authenticated roles are denied all
-- access through the REST API, while the Go backend (direct connection as table
-- owner) and service-role scripts continue to bypass RLS and work unchanged.
--
-- ENABLE (not FORCE) is deliberate so the owner/service role keep full access.
do $$
declare r record;
begin
  for r in
    select tablename from pg_tables where schemaname = 'public'
  loop
    execute format('alter table public.%I enable row level security;', r.tablename);
  end loop;
end $$;

-- ======================================================================
-- 20260809120000_old_stack_items.sql
-- ======================================================================

-- Tools a user used to run but no longer actively uses (e.g. HubSpot at a
-- previous company). Mirrors stack_items / watchlist_items. A tool lives in at
-- most one of the three lists; the add handlers enforce that mutual exclusivity.
CREATE TABLE old_stack_items (
    profile_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    tool_id UUID NOT NULL REFERENCES tools(id) ON DELETE CASCADE,
    added_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (profile_id, tool_id)
);

ALTER TABLE old_stack_items ENABLE ROW LEVEL SECURITY;

