-- ======================================================================

-- Uploaded profile picture. NULL means the user hasn't uploaded one, in which
-- case the UI falls back to their Gravatar (via email_hash), then to initials.
ALTER TABLE profiles ADD COLUMN avatar_url TEXT;

-- ======================================================================
-- 20260809180000_profile_focus_areas.sql
-- ======================================================================

-- GTM focus areas chosen during onboarding ("What's your focus?").
-- These are a curated taxonomy owned by the app, not rows in `categories`
-- (which holds the much more granular vendor-directory categories), so they are
-- stored as plain text keys rather than foreign keys.
ALTER TABLE profiles ADD COLUMN focus_areas TEXT[] NOT NULL DEFAULT '{}';

-- Marks that the user has been through the multi-step onboarding, so the flow
-- is not shown again to people who already have a profile.
ALTER TABLE profiles ADD COLUMN onboarding_completed_at TIMESTAMPTZ;

-- ======================================================================
-- 20260912120000_tool_page_ownership.sql
-- ======================================================================

-- Vendor-side ownership of a tool page. Several people from the same company
-- may own one tool, and one person may own several, so this is a join table
-- rather than a column on tools. Ownership is granted by hand once a claim
-- submitted through the "Claim this page" form has been verified — there is
-- deliberately no HTTP endpoint that grants it.
CREATE TABLE tool_owners (
    tool_id UUID NOT NULL REFERENCES tools(id) ON DELETE CASCADE,
    profile_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    granted_by UUID REFERENCES profiles(id) ON DELETE SET NULL,
    granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (tool_id, profile_id)
);

-- "Which tools does this person own?" for profile pages and the claim script.
CREATE INDEX idx_tool_owners_profile ON tool_owners (profile_id);

ALTER TABLE tool_owners ENABLE ROW LEVEL SECURITY;

-- Owner-written page copy, stored as Tiptap JSON — the same editor playbooks
-- use. tools.description stays a plain-text projection of it, so search,
-- embeddings and the catalogue cards keep working untouched.
ALTER TABLE tools ADD COLUMN description_rich TEXT;

-- Appending a column is all CREATE OR REPLACE VIEW allows; the existing ones
-- keep their names, types and order. t.id is the primary key, so the extra
-- column is functionally dependent on the GROUP BY and needs no entry there.
CREATE OR REPLACE VIEW tools_with_details WITH (security_invoker='on') AS
    SELECT t.id,
        t.name,
        t.description,
        t.logo_url,
        t.created_at,
        t.updated_at,
        COALESCE(jsonb_agg(DISTINCT jsonb_build_object('id', c.id, 'name', c.name)) FILTER (WHERE (c.id IS NOT NULL)), '[]'::jsonb) AS categories,
        jsonb_build_object('id', v.id, 'website', v.website, 'x_profile', v.x_profile, 'linkedin_profile', v.linkedin_profile, 'head_office', v.head_office, 'year_of_foundation', v.year_of_foundation) AS vendor,
        t.description_rich
    FROM (((tools t
        LEFT JOIN tool_categories tc ON ((t.id = tc.tool_id)))
        LEFT JOIN categories c ON ((tc.category_id = c.id)))
        LEFT JOIN vendors v ON ((t.vendor_id = v.id)))
    GROUP BY t.id, t.name, t.description, t.logo_url, t.created_at, t.updated_at, v.id;

-- ======================================================================
-- 20260919210000_pin_email_hash_function_search_path.sql
-- ======================================================================

-- update_profile_email_hash() and fill_profile_email_hash() are SECURITY
-- DEFINER but pin no search_path, so they resolve `digest()` and
-- `public.profiles` against whatever search_path the *caller* happens to have.
--
-- update_profile_email_hash() is a trigger on auth.users, so its caller is
-- GoTrue, connecting as supabase_auth_admin — whose search_path is `auth`
-- alone. `digest()` lives in the extensions schema, which is not on that path,
-- so every user creation fails with:
--
--   function digest(text, unknown) does not exist (SQLSTATE 42883)
--
-- This never surfaced in production only because that database's roles happen
-- to be configured with extensions on the path. Relying on that is fragile —
-- and for a SECURITY DEFINER function it is also the classic search_path
-- injection weakness, since a caller controls which schema an unqualified name
-- resolves to while the body runs with the definer's privileges.
--
-- Pinning the path fixes both. No function body changes, so this is safe to
-- apply to a database where these functions already exist.

ALTER FUNCTION update_profile_email_hash()
    SET search_path = public, extensions, pg_temp;

ALTER FUNCTION fill_profile_email_hash()
    SET search_path = public, extensions, pg_temp;

